def count_paths(H: int, W: int, K: int, grid: list[str]) -> int:
    """Count paths of K moves through distinct orthogonally adjacent empty cells.

    Paths may start at any empty cell; opposite directions count separately.
    H and W are at most 10, and K is at most 11.

    >>> count_paths(2, 2, 2, ['.#', '..'])
    2
    >>> count_paths(2, 3, 1, ['.#.', '#.#'])
    0
    """
    cells = [(r, c) for r in range(H) for c in range(W) if grid[r][c] == '.']
    if len(cells) <= K:
        return 0
    indices = {cell: i for i, cell in enumerate(cells)}
    neighbors = [[] for _ in cells]
    for i, (r, c) in enumerate(cells):
        for dr, dc in ((-1, 0), (1, 0), (0, -1), (0, 1)):
            j = indices.get((r + dr, c + dc))
            if j is not None:
                neighbors[i].append(j)

    visited = [False] * len(cells)

    def dfs(cell, remaining):
        if remaining == 0:
            return 1
        total = 0
        for nxt in neighbors[cell]:
            if not visited[nxt]:
                visited[nxt] = True
                total += dfs(nxt, remaining - 1)
                visited[nxt] = False
        return total

    total = 0
    for start in range(len(cells)):
        visited[start] = True
        total += dfs(start, K)
        visited[start] = False
    return total

def count_power_representations(n: int) -> int:
    """Count integers in [1, n] expressible as a**b with a >= 1 and b >= 2."""
    # Every base >= 2 has exponent at most floor(log2(n)).
    limit = n.bit_length() - 1
    mu = [1] * (limit + 1)
    prime = [True] * (limit + 1)
    for p in range(2, limit + 1):
        if prime[p]:
            for multiple in range(p, limit + 1, p):
                prime[multiple] = False
                mu[multiple] *= -1
            for multiple in range(p * p, limit + 1, p * p):
                mu[multiple] = 0

    def integer_root(exponent: int) -> int:
        # The upper bound raised to exponent is strictly greater than n.
        low = 1
        high = 1 << ((n.bit_length() + exponent - 1) // exponent)
        while high - low > 1:
            middle = (low + high) // 2
            if middle ** exponent <= n:
                low = middle
            else:
                high = middle
        return low

    # Include 1 once. For every other perfect power, inclusion-exclusion
    # over divisors of its maximal exponent gives total weight exactly one.
    answer = 1
    for exponent in range(2, limit + 1):
        if mu[exponent]:
            answer -= mu[exponent] * (integer_root(exponent) - 1)
    return answer

def count_good_string_replacements(n: int, k: int, s: str) -> int:
    """Count replacements having at least k erasable, nonempty substrings.

    Equal pairs and ABC triples can be deleted in any order. Thus a
    substring is erasable exactly when its three character counts have
    equal parity. Return the number of replacements modulo 998244353.
    """
    mod = 998244353
    if k == 0:
        return pow(3, s.count('?'), mod)
    # Consecutive prefix states differ, so no state occurs more than
    # ceil((n + 1) / 2) times. Two alternating states attain this bound.
    length = len(s)
    if k > length * length // 4:
        return 0

    # Encode A, B, C as the three nonzero elements of Z_2^2.
    # Store the four prefix-state frequencies relative to the current
    # prefix state. This removes the need to store the current state.
    dp = {(1, 0, 0, 0): 1}
    codes = {'A': 1, 'B': 2, 'C': 3}
    for ch in s:
        nxt = {}
        choices = (1, 2, 3) if ch == '?' else (codes[ch],)
        for (a, b, c, d), ways in dp.items():
            for code in choices:
                if code == 1:
                    state = (b + 1, a, d, c)
                elif code == 2:
                    state = (c + 1, d, a, b)
                else:
                    state = (d + 1, c, b, a)
                nxt[state] = (nxt.get(state, 0) + ways) % mod
        dp = nxt
    return sum(ways for counts, ways in dp.items()
               if sum(x * (x - 1) // 2 for x in counts) >= k) % mod

from functools import lru_cache
from math import gcd


@lru_cache(maxsize=None)
def _suffix_count(length: int, digit_sum: int, divisor: int) -> int:
    """Count nonzero-digit suffixes with a given sum and product requirement."""
    if length == 0:
        return int(digit_sum == 0 and divisor == 1)
    if digit_sum < length or digit_sum > 9 * length:
        return 0
    return sum(
        _suffix_count(length - 1, digit_sum - digit, divisor // gcd(divisor, digit))
        for digit in range(max(1, digit_sum - 9 * (length - 1)),
                           min(9, digit_sum - (length - 1)) + 1)
    )


def _smooth(value: int) -> bool:
    for prime in (2, 3, 5, 7):
        while value % prime == 0:
            value //= prime
    return value == 1


def _count_up_to(bound: int) -> int:
    if bound <= 0:
        return 0
    digits = tuple(map(int, str(bound)))
    size = len(digits)

    # Every positive number containing a zero has zero digit product.
    nonzero = sum(9 ** length for length in range(1, size))
    for index, digit in enumerate(digits):
        if digit == 0:
            break
        nonzero += (digit - 1) * 9 ** (size - index - 1)
    else:
        nonzero += 1

    beautiful_nonzero = 0
    for target_sum in range(1, 9 * size + 1):
        # A nonzero digit product has no prime factors greater than seven.
        if not _smooth(target_sum):
            continue
        for length in range(1, size):
            beautiful_nonzero += _suffix_count(length, target_sum, target_sum)

        remaining_sum = target_sum
        divisor = target_sum
        for index, digit in enumerate(digits):
            for smaller in range(1, digit):
                beautiful_nonzero += _suffix_count(
                    size - index - 1,
                    remaining_sum - smaller,
                    divisor // gcd(divisor, smaller),
                )
            if digit == 0:
                break
            remaining_sum -= digit
            divisor //= gcd(divisor, digit)
        else:
            beautiful_nonzero += int(remaining_sum == 0 and divisor == 1)

    return bound - nonzero + beautiful_nonzero


def count_beautiful_numbers(l: int, r: int) -> int:
    """Count beautiful positive integers in the inclusive range [l, r].

    A positive integer is beautiful if the product of its digits is divisible
    by the sum of its digits.

    Args:
        l: The lower bound of the range (inclusive).
        r: The upper bound of the range (inclusive).

    Returns:
        The count of beautiful numbers in the range [l, r].

    Constraints:
        1 <= l <= r < 10^9

    >>> count_beautiful_numbers(10, 20)
    2
    >>> count_beautiful_numbers(1, 15)
    10
    >>> count_beautiful_numbers(4, 4)
    1
    """
    return _count_up_to(r) - _count_up_to(l - 1)

