from functools import lru_cache


def count_beautiful_integers(low: int, high: int, k: int) -> int:
    """Count integers in [low, high] with equal even/odd digit counts and divisible by k.

    Bounds satisfy 0 < low <= high <= 10**9, and 0 < k <= 20.
    Leading zeroes are not digits of the number.

    >>> count_beautiful_integers(10, 20, 3)
    2
    >>> count_beautiful_integers(1, 10, 1)
    1
    >>> count_beautiful_integers(5, 5, 2)
    0
    """
    def count_up_to(bound: int) -> int:
        if bound <= 0:
            return 0
        digits = tuple(map(int, str(bound)))
        length = len(digits)

        @lru_cache(maxsize=None)
        def dp(pos: int, balance: int, remainder: int,
               started: bool, tight: bool) -> int:
            if abs(balance) > length - pos:
                return 0
            if pos == length:
                return int(started and balance == 0 and remainder == 0)
            limit = digits[pos] if tight else 9
            result = 0
            for digit in range(limit + 1):
                next_tight = tight and digit == digits[pos]
                if not started and digit == 0:
                    result += dp(pos + 1, 0, 0, False, next_tight)
                else:
                    result += dp(pos + 1,
                                 balance + (1 if digit % 2 == 0 else -1),
                                 (remainder * 10 + digit) % k,
                                 True, next_tight)
            return result

        return dp(0, 0, 0, False, True)

    return count_up_to(high) - count_up_to(low - 1)

def count_paths(H: int, W: int, K: int, grid: list[str]) -> int:
    """Count paths of K moves through distinct orthogonally adjacent empty cells.

    Paths may start at any empty cell; opposite directions count separately.
    H and W are at most 10, and K is at most 11.

    >>> count_paths(2, 2, 2, ['.#', '..'])
    2
    >>> count_paths(2, 3, 1, ['.#.', '#.#'])
    0
    """
    cells = [(r, c) for r in range(H) for c in range(W) if grid[r][c] == '.']
    if len(cells) <= K:
        return 0
    if K == 0:
        return len(cells)

    indices = {cell: i for i, cell in enumerate(cells)}
    neighbors = [[] for _ in cells]
    for i, (r, c) in enumerate(cells):
        for dr, dc in ((-1, 0), (1, 0), (0, -1), (0, 1)):
            j = indices.get((r + dr, c + dc))
            if j is not None:
                neighbors[i].append(j)

    visited = [False] * len(cells)

    def dfs(cell, remaining):
        # Each unvisited neighbor completes one path on the final move.
        # Counting directly avoids a recursive call for every completed path.
        if remaining == 1:
            return sum(1 for nxt in neighbors[cell] if not visited[nxt])
        total = 0
        for nxt in neighbors[cell]:
            if not visited[nxt]:
                visited[nxt] = True
                total += dfs(nxt, remaining - 1)
                visited[nxt] = False
        return total

    total = 0
    for start in range(len(cells)):
        visited[start] = True
        total += dfs(start, K)
        visited[start] = False
    return total

