from functools import lru_cache


@lru_cache(maxsize=None)
def _count_bad_suffix(remaining: int, digit_sum: int, product: int) -> int:
    """Count nonzero-digit suffixes whose final number is not beautiful."""
    if remaining == 0:
        return int(product % digit_sum != 0)
    return sum(
        _count_bad_suffix(remaining - 1, digit_sum + digit, product * digit)
        for digit in range(1, 10)
    )


def _count_beautiful_up_to(bound: int) -> int:
    if bound <= 0:
        return 0
    digits = [int(digit) for digit in str(bound)]
    # Every positive number containing a zero is beautiful. Count only the
    # non-beautiful numbers, all of whose digits must be nonzero.
    bad = sum(_count_bad_suffix(length, 0, 1)
              for length in range(1, len(digits)))
    digit_sum = 0
    product = 1
    for index, limit in enumerate(digits):
        remaining = len(digits) - index - 1
        for digit in range(1, limit):
            bad += _count_bad_suffix(remaining, digit_sum + digit,
                                     product * digit)
        if limit == 0:
            break
        digit_sum += limit
        product *= limit
    else:
        bad += int(product % digit_sum != 0)
    return bound - bad


def count_beautiful_numbers(l: int, r: int) -> int:
    """ Count the number of beautiful numbers in the range [l, r] inclusive.

    A positive integer is called beautiful if the product of its digits is divisible by the sum of its digits.

    Args:
        l: The lower bound of the range (inclusive)
        r: The upper bound of the range (inclusive)

    Returns:
        The count of beautiful numbers in the range [l, r]

    Constraints:
        1 <= l <= r < 10^9

    >>> count_beautiful_numbers(10, 20)
    2
    >>> count_beautiful_numbers(1, 15)
    10
    >>> count_beautiful_numbers(4, 4)
    1
    """
    return _count_beautiful_up_to(r) - _count_beautiful_up_to(l - 1)

