def max_partitions_with_one_change(s: str, k: int) -> int:
    """Return the most greedy partitions obtainable with at most one edit.

    Each partition is the longest available prefix with at most k distinct
    lowercase letters. The input has length 1..10**4 and 1 <= k <= 26.
    """
    if k == 26:
        return 1

    # The unedited prefix has one deterministic state. For edited prefixes,
    # retain the best completed-partition count for each current letter mask.
    plain_mask = 0
    plain_count = 0
    edited = {}
    letters = [1 << i for i in range(26)]

    for char in s:
        bit = 1 << (ord(char) - ord("a"))
        following = {}
        for mask, count in edited.items():
            merged = mask | bit
            if merged.bit_count() > k:
                merged = bit
                count += 1
            if count > following.get(merged, -1):
                following[merged] = count

        # Spend the single edit at this position, starting from the original
        # prefix state. All later positions will use the ordinary transition.
        for replacement in letters:
            if replacement == bit:
                continue
            merged = plain_mask | replacement
            count = plain_count
            if merged.bit_count() > k:
                merged = replacement
                count += 1
            if count > following.get(merged, -1):
                following[merged] = count

        merged = plain_mask | bit
        if merged.bit_count() > k:
            plain_mask = bit
            plain_count += 1
        else:
            plain_mask = merged
        edited = following

    # The current nonempty partition has not yet been counted.
    return max(plain_count, max(edited.values(), default=0)) + 1

