from functools import lru_cache


def count_good_integers(num1: str, num2: str, min_sum: int, max_sum: int) -> int:
    """Count integers in [num1, num2] whose digit sums are in [min_sum, max_sum].

    Return the count modulo 10**9 + 7. Bounds are numeric strings up
    to 10**22, and the sum bounds are between 1 and 400.
    """
    modulus = 10**9 + 7

    def count_up_to(bound: str) -> int:
        digits = tuple(map(int, bound))
        length = len(digits)

        @lru_cache(None)
        def dp(position: int, digit_sum: int, tight: bool) -> int:
            if digit_sum > max_sum:
                return 0
            if digit_sum + 9 * (length - position) < min_sum:
                return 0
            if position == length:
                return int(min_sum <= digit_sum <= max_sum)
            limit = digits[position] if tight else 9
            return sum(
                dp(position + 1, digit_sum + digit,
                   tight and digit == limit)
                for digit in range(limit + 1)
            ) % modulus

        return dp(0, 0, True)

    # Subtract numbers below the inclusive lower bound. Leading zeroes
    # in the DP represent shorter integers and do not affect digit sums.
    return (count_up_to(num2) - count_up_to(str(int(num1) - 1))) % modulus

