def count_valid_grids(H: int, W: int, grid: list[str]) -> int:
    """Count replacements with different digits in edge-sharing cells.

    The answer is returned modulo 998244353. The grid consists of '1',
    '2', '3', and '?', and has at most 200 cells.
    """
    mod = 998244353
    # Sweep along the longer dimension so the frontier has at most 14 cells.
    if W > H:
        grid = [''.join(grid[r][c] for r in range(H)) for c in range(W)]
        H, W = W, H

    # Two bits per frontier cell; zero denotes an unvisited cell.
    dp = {0: 1}
    for r in range(H):
        for c in range(W):
            shift = 2 * c
            clear = ~(3 << shift)
            cell = grid[r][c]
            choices = (1, 2, 3) if cell == '?' else (int(cell),)
            next_dp = {}
            for state, ways in dp.items():
                above = (state >> shift) & 3
                left = (state >> (shift - 2)) & 3 if c else 0
                base = state & clear
                for color in choices:
                    if color != above and color != left:
                        new_state = base | (color << shift)
                        next_dp[new_state] = (next_dp.get(new_state, 0) + ways) % mod
            dp = next_dp
            if not dp:
                return 0
    return sum(dp.values()) % mod

from functools import lru_cache


MOD = 10**9 + 7


def count_good_integers(num1: str, num2: str, min_sum: int, max_sum: int) -> int:
    """Count integers x in [num1, num2] with digit sum in [min_sum, max_sum].

    Bounds are numeric strings with 1 <= num1 <= num2 <= 10**22.
    Return the count modulo 10**9 + 7.

    >>> count_good_integers("1", "12", 1, 8)
    11
    >>> count_good_integers("1", "5", 1, 5)
    5
    """
    def count_up_to(bound: str) -> int:
        digits = tuple(map(int, bound))
        length = len(digits)
        ceiling = min(max_sum, 9 * length)

        @lru_cache(None)
        def dp(position: int, total: int, tight: bool) -> int:
            if total > ceiling or total + 9 * (length - position) < min_sum:
                return 0
            if position == length:
                return int(min_sum <= total <= ceiling)
            limit = digits[position] if tight else 9
            result = 0
            for digit in range(min(limit, ceiling - total) + 1):
                result += dp(position + 1, total + digit,
                             tight and digit == digits[position])
            return result % MOD

        return dp(0, 0, True)

    lower_is_good = min_sum <= sum(map(int, num1)) <= max_sum
    return (count_up_to(num2) - count_up_to(num1) + lower_is_good) % MOD

from math import isqrt


def count_power_representations(n: int) -> int:
    """Count integers in [1, n] expressible as a**b with a >= 1 and b >= 2."""
    if n < 1:
        return 0

    # If x > 1 has prime factorization with exponent gcd g, then x is
    # a kth power exactly when k divides g. Thus its weight in the sum
    # below is -sum(mu(k) for k | g, k >= 2), which is 1 iff g > 1.
    limit = n.bit_length() - 1
    mu = [1] * (limit + 1)
    prime = [True] * (limit + 1)
    for p in range(2, limit + 1):
        if prime[p]:
            for multiple in range(p, limit + 1, p):
                prime[multiple] = False
                mu[multiple] *= -1
            for multiple in range(p * p, limit + 1, p * p):
                mu[multiple] = 0

    def integer_root(exponent: int) -> int:
        if exponent == 2:
            return isqrt(n)
        low = 1
        high = 1 << ((n.bit_length() + exponent - 1) // exponent)
        while high - low > 1:
            middle = (low + high) // 2
            if middle ** exponent <= n:
                low = middle
            else:
                high = middle
        return low

    # Count 1 once, and exclude base 1 from each inclusion-exclusion term.
    answer = 1
    for exponent in range(2, limit + 1):
        if mu[exponent]:
            answer -= mu[exponent] * (integer_root(exponent) - 1)
    return answer

