def count_valid_grids(H: int, W: int, grid: list[str]) -> int:
    """Count proper three-colour completions of the grid, modulo 998244353.

    H and W are positive, H * W <= 200, and each cell is 1, 2, 3 or ?.
    Edge-sharing cells must have different digits.
    """
    mod = 998244353

    # Sweep across the narrower dimension to keep the frontier small.
    if W > H:
        grid = ["".join(grid[r][c] for r in range(H)) for c in range(W)]
        H, W = W, H

    # Each two-bit field holds one frontier colour; zero marks an empty cell.
    # The oldest field is the cell above, and the newest is the cell to the left.
    mask = (1 << (2 * W)) - 1
    above_shift = 2 * (W - 1)
    dp = {0: 1}
    for row in grid:
        for col, cell in enumerate(row):
            choices = (1, 2, 3) if cell == "?" else (int(cell),)
            following = {}
            for state, count in dp.items():
                above = state >> above_shift
                left = (state & 3) if col else 0
                base = (state << 2) & mask
                for colour in choices:
                    if colour != above and colour != left:
                        new_state = base | colour
                        following[new_state] = (following.get(new_state, 0) + count) % mod
            dp = following
            if not dp:
                return 0

    return sum(dp.values()) % mod

